CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_store_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM auth.users u JOIN auth.identities i ON i.user_id=u.id WHERE u.id=auth.uid() AND lower(u.email)='gabrielouleal@gmail.com' AND u.email_confirmed_at IS NOT NULL AND i.provider='google' AND lower(i.identity_data->>'email')='gabrielouleal@gmail.com' AND i.identity_data->>'email_verified'='true') $$;
REVOKE ALL ON FUNCTION public.is_store_owner() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_store_owner() TO authenticated;
CREATE FUNCTION public.claim_store_owner() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_store_owner() THEN RETURN false; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'admin') ON CONFLICT DO NOTHING; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.claim_store_owner() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.claim_store_owner() TO authenticated;
CREATE FUNCTION public.is_store_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_store_owner() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_store_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_store_admin() TO authenticated;
CREATE TABLE public.products (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), brand text NOT NULL CHECK(length(brand) BETWEEN 1 AND 100), description text NOT NULL DEFAULT '' CHECK(length(description)<=5000), category text NOT NULL DEFAULT 'masculinos' CHECK(category IN ('masculinos','femininos','unissex')), price numeric(10,2) NOT NULL DEFAULT 0 CHECK(price>=0), original_price numeric(10,2) CHECK(original_price>price), image text NOT NULL DEFAULT '', featured boolean NOT NULL DEFAULT false, available boolean DEFAULT NULL, stock integer CHECK(stock>=0), sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated;
GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_catalog ON public.products FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_insert ON public.products FOR INSERT TO authenticated WITH CHECK(public.is_store_admin());
CREATE POLICY admin_update ON public.products FOR UPDATE TO authenticated USING(public.is_store_admin()) WITH CHECK(public.is_store_admin());
CREATE POLICY admin_delete ON public.products FOR DELETE TO authenticated USING(public.is_store_admin());
CREATE POLICY product_photo_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='product-images');
CREATE POLICY product_photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='product-images' AND public.is_store_admin());
CREATE POLICY product_photo_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='product-images' AND public.is_store_admin()) WITH CHECK(bucket_id='product-images' AND public.is_store_admin());
CREATE POLICY product_photo_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='product-images' AND public.is_store_admin());